examples:
解雇操作的结构可表示为：
```cpp
try {
    auto& emp{db.getEmployee(employeeNumber)};
    emp.fire();
    std::cout << std::format(
        "Employee {} terminated.", employeeNumber)
        << std::endl;
} catch (const std::logic_error& exception) {
    std::cerr << std::format(
        "Unable to terminate employee: {}", exception.what())
        << std::endl;
}
```

晋升操作的核心结构可表示为：
```cpp
try {
    auto& emp{db.getEmployee(employeeNumber)};
    emp.promote(raiseAmount);
} catch (const std::logic_error& exception) {
    std::cerr << std::format(
        "Unable to promote employee: {}", exception.what())
        << std::endl;
}
```
